import { describe, expect, it } from "vitest";
import {
  buildAffinityContext,
  confidencePercent,
  detectGhostSynapses,
  pairAffinity,
  scoreGhostPairs,
} from "../ghost-engine";
import { seedEdges, seedNodes } from "@/data/demo-seed";

/**
 * Spec 09 widened the MAGNETIC affinity scale (`magneticAffinity`) without touching the Ghost scan. The
 * snapshots in `__snapshots__/ghost-scan-regression.test.ts.snap` were generated by the code at the commit
 * BEFORE that change (31452c8) and must never change with it: discoveries, raw pair scores, `pairAffinity`
 * and the synapse pill percentages on the demo seed.
 */
describe("Ghost scan on the demo seed is unchanged by the magnetic affinity scale", () => {
  it("detectGhostSynapses output (ids, rationale, confidence) matches the pre-change snapshot", () => {
    expect(detectGhostSynapses(seedNodes, seedEdges)).toMatchSnapshot();
  });

  it("the unconnected-pair scan without edges matches the snapshot too", () => {
    expect(detectGhostSynapses(seedNodes, [])).toMatchSnapshot();
  });

  it("raw pair scores and pairAffinity (0 below the threshold) match the snapshot", () => {
    const ctx = buildAffinityContext(seedNodes);
    const rows = scoreGhostPairs(seedNodes).map((p) => ({
      pair: `${p.sourceId}|${p.targetId}`,
      score: p.score,
      sharedConcepts: p.sharedConcepts,
      affinity: pairAffinity({ id: p.sourceId }, { id: p.targetId }, ctx).affinity,
    }));
    expect(rows).toMatchSnapshot();
  });

  it("synapse pill percentages are round(confidence * 100) of the unchanged confidences", () => {
    const found = detectGhostSynapses(seedNodes, seedEdges);
    expect(found.map((d) => confidencePercent(d.confidence))).toEqual(found.map((d) => Math.round(d.confidence * 100)));
    expect(found.map((d) => confidencePercent(d.confidence))).toMatchSnapshot();
  });
});
